  ["...","L..","...",".C.","...",".L.","..."],
];
const before = {};
for (const [x, y, z] of [[3,4,15],[4,4,19],[4,4,17],[3,3,20]]) before[[x,y,z]] = g.get ? g.get(x,y,z) : null;
console.log("before (should be air):", JSON.stringify(before));
const n = layers(g, [3, 2, 14], LEGEND, LAYOUT);
console.log("layers placed", n);
g.save(out);
